-- LABELXR-REVIEW-CONFLICT-MIGRATION-v1
-- Preserve the four original migrations. Change only the deterministic stale signal.
BEGIN;
DO $labelxr_conflict_preflight$
DECLARE definition text;
BEGIN
 definition:=pg_get_functiondef('public.commit_review(jsonb)'::regprocedure);
 IF encode(sha256(convert_to(definition,'UTF8')),'hex') NOT IN
 ('ca6b377ac2fbf795b366272f48c698f8333b9ed5086836b43804961c9a69dfa8','b7f49d1076268ff398e1f9d848c9195764e769fba1cb88b189b013622e2e4d84') THEN
  RAISE EXCEPTION 'Review function differs from reviewed original/repaired definition';
 END IF;
END $labelxr_conflict_preflight$;
CREATE OR REPLACE FUNCTION public.commit_review(command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE owner uuid:=auth.uid();guest boolean;p public.projects;current public.label_versions;previous public.label_versions;m public.mutations;last public.mutations;pid uuid;rid uuid;base integer;op text;fid text;oid text;partner text;why text;keys text[];expected text[];payload text;labels jsonb;verdicts jsonb;old_occ jsonb;before_v jsonb;after_v jsonb;partner_v jsonb;fp text;before_audit jsonb;after_audit jsonb;
BEGIN
 IF owner IS NULL THEN RAISE EXCEPTION 'Verified account required' USING ERRCODE='42501';END IF;SELECT is_anonymous INTO guest FROM auth.users WHERE id=owner FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Verified account required' USING ERRCODE='42501';END IF;
 PERFORM labelroom_private.review_need(jsonb_typeof(command)='object' AND octet_length(command::text)<=16384,'Bounded command required');op:=command->>'operation';expected:=ARRAY['projectId','requestId','baseRevision','operation','frameId','objectId','reason'];IF op='updateCuboid' THEN expected:=expected||ARRAY['before','after'];ELSIF op='keepIssue' THEN expected:=expected||ARRAY['before','issue','fingerprint'];ELSIF op='removeDuplicate' THEN expected:=expected||ARRAY['before','partnerId','partnerBefore','confirmed'];ELSIF op='undo' THEN expected:=expected||ARRAY['undoOf'];ELSE PERFORM labelroom_private.review_need(false,'Unknown review operation');END IF;SELECT array_agg(k ORDER BY k) INTO keys FROM jsonb_object_keys(command) k;PERFORM labelroom_private.review_need(cardinality(keys)=cardinality(expected) AND command ?& expected,'Unexpected command fields');
 PERFORM labelroom_private.review_need(jsonb_typeof(command->'projectId')='string' AND command->>'projectId' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND jsonb_typeof(command->'requestId')='string' AND command->>'requestId' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$','Invalid UUID');pid:=(command->>'projectId')::uuid;rid:=(command->>'requestId')::uuid;PERFORM labelroom_private.review_need(jsonb_typeof(command->'baseRevision')='number' AND (command->>'baseRevision')::numeric BETWEEN 0 AND 300 AND (command->>'baseRevision')::numeric=trunc((command->>'baseRevision')::numeric),'Invalid base revision');base:=(command->>'baseRevision')::integer;fid:=labelroom_private.review_id(command->'frameId');oid:=labelroom_private.review_id(command->'objectId');why:=command->>'reason';PERFORM labelroom_private.review_need(why IN ('occlusion','valid-geometry','duplicate','other') AND jsonb_typeof(command->'reason')='string','Invalid reason');
 SELECT * INTO p FROM public.projects WHERE id=pid AND owner_id=owner FOR UPDATE;IF NOT FOUND OR p.status<>'ready' OR (p.kind='demo') IS DISTINCT FROM guest OR (guest AND p.expires_at<=now()) THEN RAISE EXCEPTION 'Owned live project required' USING ERRCODE='42501';END IF;payload:=labelroom_private.review_hash(jsonb_build_array('labelxr-review-command/v1',p.source_hash,command));SELECT * INTO m FROM public.mutations WHERE owner_id=owner AND request_id=rid;IF FOUND THEN PERFORM labelroom_private.review_need(m.project_id=pid AND m.payload_hash=payload AND m.revision=base+1,'Request UUID was used for another command');RETURN labelroom_private.review_receipt(m);END IF;IF p.current_revision<>base THEN RAISE EXCEPTION 'Stale review revision' USING ERRCODE='PT409';END IF;IF base>=300 THEN RAISE EXCEPTION 'Review revision limit reached' USING ERRCODE='23514';END IF;
 SELECT * INTO STRICT current FROM public.label_versions WHERE project_id=pid AND revision=base;labels:=current.label_doc;verdicts:=current.review_verdicts;PERFORM labelroom_private.review_need(EXISTS(SELECT 1 FROM jsonb_array_elements(p.manifest->'frames') f WHERE f->>'id'=fid),'Unknown frame');old_occ:=labels#>ARRAY['openlabel','frames',fid,'objects',oid];before_v:=old_occ#>'{object_data,cuboid,0,val}';
 IF op='undo' THEN SELECT * INTO last FROM public.mutations WHERE project_id=pid AND revision=base;PERFORM labelroom_private.review_need(FOUND AND last.operation<>'undo' AND last.request_id::text=command->>'undoOf' AND last.request_id<>rid AND last.frame_id=fid AND last.object_id=oid AND why='other' AND jsonb_typeof(command->'undoOf')='string','Only latest committed decision may be undone once');SELECT * INTO STRICT previous FROM public.label_versions WHERE project_id=pid AND revision=base-1;labels:=previous.label_doc;verdicts:=previous.review_verdicts;before_audit:=last.after_doc;after_audit:=last.before_doc;
 ELSE PERFORM labelroom_private.review_box(before_v);PERFORM labelroom_private.review_box(command->'before');PERFORM labelroom_private.review_need(before_v=command->'before','Exact before geometry differs');
 IF op='updateCuboid' THEN after_v:=command->'after';PERFORM labelroom_private.review_box(after_v);PERFORM labelroom_private.review_need(after_v<>before_v,'Geometry update is unchanged');labels:=jsonb_set(labels,ARRAY['openlabel','frames',fid,'objects',oid,'object_data','cuboid','0','val'],after_v,false);before_audit:=before_v;after_audit:=after_v;
 ELSIF op='removeDuplicate' THEN partner:=labelroom_private.review_id(command->'partnerId');PERFORM labelroom_private.review_need(partner<>oid AND why='duplicate' AND command->'confirmed'='true'::jsonb,'Explicit different duplicate partner required');partner_v:=labels#>ARRAY['openlabel','frames',fid,'objects',partner,'object_data','cuboid','0','val'];PERFORM labelroom_private.review_box(partner_v);PERFORM labelroom_private.review_box(command->'partnerBefore');PERFORM labelroom_private.review_need(partner_v=command->'partnerBefore' AND labels#>ARRAY['openlabel','objects',oid,'type']=labels#>ARRAY['openlabel','objects',partner,'type'],'Duplicate partner geometry/class differs');PERFORM labelroom_private.review_need(labelroom_private.review_iou(before_v,partner_v)>=0.90,'Duplicate oriented IoU below 0.90');labels:=labels#-ARRAY['openlabel','frames',fid,'objects',oid];before_audit:=old_occ;after_audit:='null';
 ELSE fp:=labelroom_private.review_fingerprint(p,labels,fid,command->'issue');PERFORM labelroom_private.review_need(jsonb_typeof(command->'fingerprint')='string' AND command->>'fingerprint'=fp AND (command->'issue'->'objectIds') ? oid,'Stale issue fingerprint');before_audit:=coalesce(verdicts->fp,'null');after_audit:=jsonb_build_object('issue',command->'issue','frameId',fid,'objectId',oid,'reason',why,'revision',base+1);verdicts:=verdicts||jsonb_build_object(fp,after_audit);END IF;END IF;
 PERFORM labelroom_private.review_need(octet_length(labelroom_private.review_canonical(labels))<=2097152 AND octet_length(labelroom_private.review_canonical(verdicts))<=2097152,'Snapshot exceeds bounded JSON size');INSERT INTO public.label_versions(project_id,revision,label_doc,review_verdicts) VALUES(pid,base+1,labels,verdicts);INSERT INTO public.mutations(request_id,project_id,revision,owner_id,operation,frame_id,object_id,partner_id,before_doc,after_doc,reason,payload_hash,undo_of) VALUES(rid,pid,base+1,owner,op,fid,oid,partner,before_audit,after_audit,why,payload,CASE WHEN op='undo' THEN last.id ELSE NULL END) RETURNING * INTO m;UPDATE public.projects SET current_revision=base+1 WHERE id=pid;RETURN labelroom_private.review_receipt(m);END $function$;
DO $labelxr_conflict_postcheck$
BEGIN
 IF encode(sha256(convert_to(pg_get_functiondef('public.commit_review(jsonb)'::regprocedure),'UTF8')),'hex')
 <> 'b7f49d1076268ff398e1f9d848c9195764e769fba1cb88b189b013622e2e4d84' THEN RAISE EXCEPTION 'Repaired review function hash differs';END IF;
END $labelxr_conflict_postcheck$;
COMMIT;
